import { readFileSync,writeFileSync } from 'node:fs';
const pkg='infrastructure/upgrades/launch-readiness-v2';
const manifestPath=`${pkg}/manifest.json`;
const manifest=JSON.parse(readFileSync(manifestPath,'utf8'));
manifest.requiredToolchain.npm='10.9.8';
manifest.requiredToolchain.terraform='1.15.0';
writeFileSync(manifestPath,JSON.stringify(manifest,null,2)+'\n');
const packagePath='package.json';
const packageJson=JSON.parse(readFileSync(packagePath,'utf8'));
packageJson.packageManager='npm@10.9.8';
writeFileSync(packagePath,JSON.stringify(packageJson,null,2)+'\n');
const providersPath=`${pkg}/providers.mjs`;
let providers=readFileSync(providersPath,'utf8');
const before="const terraform=JSON.parse(await run('terraform',['version','-json'],{timeoutMs:30000}));requireThat(/^\\d+\\.\\d+\\.\\d+/u.test(terraform.terraform_version ?? ''),'Terraform CLI is unavailable or invalid');versions.terraform=terraform.terraform_version;";
const after="const terraform=JSON.parse(await run('terraform',['version','-json'],{timeoutMs:30000}));versions.terraform=terraform.terraform_version;requireThat(versions.terraform===manifest.requiredToolchain.terraform,`Wrong Terraform version; require ${manifest.requiredToolchain.terraform}`);";
if(!providers.includes(before))throw new Error('Terraform toolchain patch anchor missing');
providers=providers.replace(before,after);
writeFileSync(providersPath,providers);
const readmePath=`${pkg}/README.md`;
let readme=readFileSync(readmePath,'utf8');
if(!readme.includes('npm 10.9.8'))readme+='\n\nV2.6 also aligns the operator toolchain with Node 22.23.2 as distributed in CI: npm 10.9.8 and Terraform 1.15.0 are now explicit live-doctor requirements. This prevents a clean Node selection from failing solely because the manifest pinned an older bundled npm.\n';
writeFileSync(readmePath,readme);
